import{_ as a,o as n,c as e,a2 as o}from"./chunks/framework.BBd5PKnH.js";const i="/dev-notes/assets/storage-vs-compute-01.BxGYEpnx.png",r="/dev-notes/assets/storage-vs-compute-02.CqJXfhlm.png",l="/dev-notes/assets/storage-vs-compute-03.ma4LuLAU.png",h="/dev-notes/assets/storage-vs-compute-04.qV3aD2AM.png",c="/dev-notes/assets/storage-vs-compute-05.nSG9sWAM.png",s="/dev-notes/assets/storage-vs-compute-06.Wm3Ch1L5.png",g="/dev-notes/assets/storage-vs-compute-07.Dtufrohx.png",q=JSON.parse('{"title":"Tách storage và compute trong cloud","description":"","frontmatter":{},"headers":[],"relativePath":"cloud/storage-vs-compute.md","filePath":"cloud/storage-vs-compute.md"}'),u={name:"cloud/storage-vs-compute.md"};function d(m,t,p,b,v,k){return n(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="tach-storage-va-compute-trong-cloud" tabindex="-1">Tách storage và compute trong cloud <a class="header-anchor" href="#tach-storage-va-compute-trong-cloud" aria-label="Permalink to &quot;Tách storage và compute trong cloud&quot;">​</a></h1><p>Ghi chú tổng hợp từ DDIA (bản 2), Chương 1, mục &quot;Separation of storage and compute&quot; (tr.13–16), kèm phân tích, ví dụ và tài liệu mới.</p><hr><h2 id="_1-compute-va-storage-la-gi" tabindex="-1">1. Compute và storage là gì? <a class="header-anchor" href="#_1-compute-va-storage-la-gi" aria-label="Permalink to &quot;1. Compute và storage là gì?&quot;">​</a></h2><p><img src="'+i+'" alt="Compute và storage"></p><p><strong>So sánh dễ nhớ (thư viện):</strong></p><ul><li>Storage = kho sách: to, rẻ, ít thay đổi.</li><li>Compute = người đọc ngồi ở bàn: tốn chi phí, số lượng lên xuống theo giờ.</li><li>Kiến trúc truyền thống: mỗi người đọc tự mang theo nguyên kho sách.</li><li>Kiến trúc tách rời: một kho chung, đông người thì kê thêm bàn, vắng thì cất bàn.</li></ul><p><strong>Liên hệ thực tế:</strong> service FastAPI trên ECS là compute thuần; Redis, RDS, S3 là nơi giữ state. Đó là lý do container nên stateless.</p><hr><h2 id="_2-ba-cach-luu-du-lieu-tren-cloud" tabindex="-1">2. Ba cách lưu dữ liệu trên cloud <a class="header-anchor" href="#_2-ba-cach-luu-du-lieu-tren-cloud" aria-label="Permalink to &quot;2. Ba cách lưu dữ liệu trên cloud&quot;">​</a></h2><h3 id="_2-1-instance-store-đia-local-that" tabindex="-1">2.1. Instance store (đĩa local thật) <a class="header-anchor" href="#_2-1-instance-store-đia-local-that" aria-label="Permalink to &quot;2.1. Instance store (đĩa local thật)&quot;">​</a></h3><ul><li>SSD/NVMe gắn trực tiếp vào máy vật lý đang chạy VM.</li><li>Rất nhanh (độ trễ cỡ micro giây), không đi qua mạng.</li><li>VM bị stop, hỏng, hoặc dời sang máy khác → <strong>mất dữ liệu</strong>.</li><li>Cloud native coi nó như <strong>cache tạm</strong>, không phải nơi lưu lâu dài.</li><li>Trên AWS: chỉ một số loại instance có (ví dụ dòng có chữ <code>d</code>: <code>m5d</code>, <code>i3</code>, <code>i4i</code>).</li></ul><h3 id="_2-2-đia-ao-ebs-azure-managed-disk-gcp-persistent-disk" tabindex="-1">2.2. Đĩa ảo (EBS, Azure managed disk, GCP persistent disk) <a class="header-anchor" href="#_2-2-đia-ao-ebs-azure-managed-disk-gcp-persistent-disk" aria-label="Permalink to &quot;2.2. Đĩa ảo (EBS, Azure managed disk, GCP persistent disk)&quot;">​</a></h3><ul><li>Là <strong>một cụm máy chủ lưu trữ riêng</strong>, nằm ở chỗ khác trong data center. Bên trong vẫn là SSD vật lý.</li><li>VM &quot;thấy&quot; nó như một ổ đĩa (<code>/dev/nvme1n1</code>), format và mount bình thường.</li><li>Thực chất mỗi lần đọc/ghi một block (thường 4 KiB) là <strong>một request qua mạng</strong>.</li><li>Mỗi block được nhân bản sang nhiều máy trong cùng Availability Zone.</li><li>Tháo ra được, gắn sang VM khác được → dữ liệu sống độc lập với máy tính toán.</li><li>Lưu ý: phần lớn EC2 hiện nay <strong>mặc định đã dùng EBS làm ổ gốc</strong>.</li></ul><p><img src="'+r+'" alt="Instance store và EBS"></p><p><strong>Tương tự on-premise:</strong> VMware thường để VM trên SAN/vSAN (lưu trữ dùng chung), nhờ vậy mới làm được vMotion. EBS là phiên bản &quot;dịch vụ thuê&quot; của ý tưởng này.</p><h3 id="_2-3-dich-vu-luu-tru-chuyen-dung-cach-cloud-native-chon" tabindex="-1">2.3. Dịch vụ lưu trữ chuyên dụng (cách cloud native chọn) <a class="header-anchor" href="#_2-3-dich-vu-luu-tru-chuyen-dung-cach-cloud-native-chon" aria-label="Permalink to &quot;2.3. Dịch vụ lưu trữ chuyên dụng (cách cloud native chọn)&quot;">​</a></h3><ul><li>Object storage (S3, Azure Blob, Cloudflare R2): phù hợp file lớn (vài trăm KB đến vài GB).</li><li>Database cloud native: quản lý giá trị nhỏ ở một dịch vụ riêng, gom nhiều giá trị thành block lớn để lưu trên object store.</li><li>Hoặc tầng storage riêng được thiết kế cho chính database đó (Aurora storage).</li></ul><hr><h2 id="_3-nhuoc-điem-cua-đia-ao" tabindex="-1">3. Nhược điểm của đĩa ảo <a class="header-anchor" href="#_3-nhuoc-điem-cua-đia-ao" aria-label="Permalink to &quot;3. Nhược điểm của đĩa ảo&quot;">​</a></h2><h3 id="_3-1-đo-tre" tabindex="-1">3.1. Độ trễ <a class="header-anchor" href="#_3-1-đo-tre" aria-label="Permalink to &quot;3.1. Độ trễ&quot;">​</a></h3><ul><li>NVMe local: vài chục đến ~100 micro giây.</li><li>EBS: dưới 1 ms đến ~1 ms → chậm hơn từ khoảng 10 lần trở lên mỗi thao tác.</li><li>App web thường không cảm nhận được; database làm hàng nghìn I/O nhỏ mỗi giây thì cộng dồn rất nhanh.</li></ul><h3 id="_3-2-phu-thuoc-mang" tabindex="-1">3.2. Phụ thuộc mạng <a class="header-anchor" href="#_3-2-phu-thuoc-mang" aria-label="Permalink to &quot;3.2. Phụ thuộc mạng&quot;">​</a></h3><ul><li>Ổ local: chạy hoặc hỏng hẳn.</li><li>EBS: có thêm trạng thái lưng chừng — mạng nghẽn làm I/O <strong>treo</strong> vài giây.</li><li>Ví dụ: Postgres commit transaction phải chờ WAL ghi xong; mạng tới EBS nghẽn 3 giây → mọi transaction đứng chờ, API timeout, dù CPU/RAM của EC2 vẫn rảnh.</li></ul><h3 id="_3-3-overhead-cua-viec-gia-lam-o-đia" tabindex="-1">3.3. Overhead của việc &quot;giả làm ổ đĩa&quot; <a class="header-anchor" href="#_3-3-overhead-cua-viec-gia-lam-o-đia" aria-label="Permalink to &quot;3.3. Overhead của việc &quot;giả làm ổ đĩa&quot;&quot;">​</a></h3><p>EBS không biết bên trên là database, nó chỉ thấy block. Hệ quả:</p><ul><li><strong>Ghi cả page dù chỉ đổi vài byte:</strong> update 1 dòng 50 byte → Postgres ghi nguyên page 8 KB (≈ 160 lần), tương đương 2 block EBS gửi qua mạng.</li><li><strong>Nhân bản hai lần:</strong> database tự có replica, EBS bên dưới lại nhân bản từng block thêm lần nữa.</li><li><strong>Giới hạn IOPS/throughput theo volume:</strong> vượt trần là bị bóp, dù máy còn khỏe.</li><li><strong>Gắn với 1 AZ:</strong> không gắn được sang EC2 ở AZ khác.</li></ul><p><img src="'+l+'" alt="Postgres trên EBS"></p><p><strong>Ví dụ đời thường:</strong> sửa một chữ trong tài liệu Word 100 trang, nhưng phải gửi lại nguyên trang chứa chữ đó, rồi cả bạn lẫn dịch vụ lưu trữ đều tự photo thêm vài bản.</p><hr><h2 id="_4-aurora-giai-quyet-the-nao-the-log-is-the-database" tabindex="-1">4. Aurora giải quyết thế nào: &quot;the log is the database&quot; <a class="header-anchor" href="#_4-aurora-giai-quyet-the-nao-the-log-is-the-database" aria-label="Permalink to &quot;4. Aurora giải quyết thế nào: &quot;the log is the database&quot;&quot;">​</a></h2><ul><li>Instance chỉ gửi <strong>bản ghi log mô tả thay đổi</strong> (kiểu &quot;dòng X đổi từ A thành B&quot;) xuống tầng storage.</li><li>Tầng storage <strong>hiểu database</strong>, tự dựng lại page từ log.</li><li>Dữ liệu được giữ 6 bản qua 3 AZ, chỉ ở tầng storage (nhân bản một lần).</li><li>Reader dùng chung storage với writer, không giữ bản dữ liệu riêng.</li><li>Theo paper gốc: chỉ ghi redo log xuống storage giúp giảm số I/O mỗi transaction khoảng 8 lần (7,4 → 0,95 so với MySQL mirrored).</li></ul><p><img src="'+h+'" alt="Aurora"></p><p><img src="'+c+'" alt="Postgres trên EBS và Aurora"></p><p><strong>Ví dụ đời thường:</strong> thay vì gửi lại nguyên trang, chỉ gửi một dòng &quot;trang 37, dòng 5, đổi chữ A thành B&quot;; bên lưu trữ tự sửa vào bản gốc.</p><hr><h2 id="_5-loi-ich-khi-tach-storage-va-compute" tabindex="-1">5. Lợi ích khi tách storage và compute <a class="header-anchor" href="#_5-loi-ich-khi-tach-storage-va-compute" aria-label="Permalink to &quot;5. Lợi ích khi tách storage và compute&quot;">​</a></h2><p><img src="'+s+'" alt="Lợi ích khi tách storage và compute"></p><p><strong>Cái giá phải trả:</strong> mọi thứ thành lời gọi mạng → latency và độ ổn định mạng quyết định hiệu năng.</p><hr><h2 id="_6-dien-bien-2025-hai-huong-đi" tabindex="-1">6. Diễn biến 2025: hai hướng đi <a class="header-anchor" href="#_6-dien-bien-2025-hai-huong-đi" aria-label="Permalink to &quot;6. Diễn biến 2025: hai hướng đi&quot;">​</a></h2><p><img src="'+g+'" alt="Hai hướng đi 2025"></p><p>Số liệu từ PlanetScale: một workload ~1 triệu QPS có độ trễ I/O ~1 ms trên ổ mạng, xuống mức micro giây trên NVMe local. Depot chuyển từ 8 CPU + EBS xuống 4 CPU + NVMe vì hết thời gian chờ I/O.</p><p><strong>Điểm chung:</strong> cả hai đều tránh EBS đứng giữa như một &quot;ổ đĩa giả&quot; không hiểu database.</p><hr><h2 id="_7-bai-hoc-thiet-ke" tabindex="-1">7. Bài học thiết kế <a class="header-anchor" href="#_7-bai-hoc-thiet-ke" aria-label="Permalink to &quot;7. Bài học thiết kế&quot;">​</a></h2><ol><li>Container/service nên <strong>stateless</strong>; đừng ghi state quan trọng vào đĩa local của container.</li><li>Đẩy state ra dịch vụ chuyên dụng: Redis/ElastiCache, RDS/Aurora, S3.</li><li>Redis chạy trong task ECS ghi vào đĩa local → task bị reschedule là mất dữ liệu.</li><li>Khi debug latency database trên EBS, xem cả metric của volume (IOPS, throughput, queue length), không chỉ CPU/RAM.</li><li>&quot;Postgres chạy trên EC2/RDS&quot; là phần mềm truyền thống đem lên cloud; &quot;Aurora&quot; mới là cloud native thật sự.</li></ol><hr><h2 id="_8-tai-lieu-đoc-them" tabindex="-1">8. Tài liệu đọc thêm <a class="header-anchor" href="#_8-tai-lieu-đoc-them" aria-label="Permalink to &quot;8. Tài liệu đọc thêm&quot;">​</a></h2><p><strong>Kinh điển</strong></p><ul><li>Amazon Aurora paper (SIGMOD 2017): <a href="https://pdos.csail.mit.edu/6.824/papers/aurora.pdf" target="_blank" rel="noreferrer">https://pdos.csail.mit.edu/6.824/papers/aurora.pdf</a> → Đọc Section 1, 3.1–3.2; xem Figure 2 và Figure 3.</li><li>Tóm tắt của The Morning Paper: <a href="https://blog.acolyer.org/2019/03/25/amazon-aurora-design-considerations-for-high-throughput-cloud-native-relational-databases/" target="_blank" rel="noreferrer">https://blog.acolyer.org/2019/03/25/amazon-aurora-design-considerations-for-high-throughput-cloud-native-relational-databases/</a></li></ul><p><strong>Mới (2025)</strong></p><ul><li>Xiangyao Yu, <em>Disaggregation: A New Architecture for Cloud Databases</em> (VLDB 2025, 4 trang): <a href="https://vldb.org/pvldb/vol18/p5527-xiangyao.pdf" target="_blank" rel="noreferrer">https://vldb.org/pvldb/vol18/p5527-xiangyao.pdf</a></li><li>Tóm tắt của Murat Demirbas: <a href="https://muratbuffalo.blogspot.com/2025/09/disaggregation-new-architecture-for.html" target="_blank" rel="noreferrer">https://muratbuffalo.blogspot.com/2025/09/disaggregation-new-architecture-for.html</a></li><li>PlanetScale Metal: <a href="https://planetscale.com/blog/planetscale-metal-theres-no-replacement-for-displacement" target="_blank" rel="noreferrer">https://planetscale.com/blog/planetscale-metal-theres-no-replacement-for-displacement</a></li><li>Case study Depot: <a href="https://depot.dev/blog/faster-database-with-planetscale-metal" target="_blank" rel="noreferrer">https://depot.dev/blog/faster-database-with-planetscale-metal</a></li><li>Marc Brooker về Aurora DSQL: <a href="https://brooker.co.za/blog/2024/12/04/inside-dsql/" target="_blank" rel="noreferrer">https://brooker.co.za/blog/2024/12/04/inside-dsql/</a></li><li>Loạt bài DeNA về DSQL: <a href="https://engineering.dena.com/blog/2025/07/aurora-dsql_01_aurora_en/" target="_blank" rel="noreferrer">https://engineering.dena.com/blog/2025/07/aurora-dsql_01_aurora_en/</a></li><li>AWS 10 năm Aurora: <a href="https://aws.amazon.com/blogs/aws/celebrating-10-years-of-amazon-aurora-innovation" target="_blank" rel="noreferrer">https://aws.amazon.com/blogs/aws/celebrating-10-years-of-amazon-aurora-innovation</a></li></ul><p><strong>Thứ tự đọc gợi ý:</strong> blog Murat (15 phút) → PlanetScale Metal (thấy mặt trái của EBS bằng số liệu) → Aurora paper → Marc Brooker về DSQL.</p>',54)])])}const f=a(u,[["render",d]]);export{q as __pageData,f as default};
